// Hand-written "bundle" for the api.bundle_routes end-to-end run (N16).
// It is a real JavaScript file, just a very small one. Each construct below
// exists to exercise exactly one branch of the scanner:
//
//   B = "..."          a plain path literal        -> a route, offset cited
//   fetch("/api/...")  a plain literal argument    -> recovered_from "fetch"
//   fetch(`...${id}`)  a template literal          -> "/api/v2/orders/{}", interpolated
//   "..." + id         a concatenated route        -> partial: true, fragment only
//   axios.post(...)                                -> recovered_from "axios.post"
//   $.ajax({url: ...})                             -> recovered_from "jquery.ajax"
//   "/static/app.css"  a static asset path         -> skipped_non_route, never a route
//   the comment below  a path in a // comment      -> not a token at all
//
// Text in this header names routes too ("/api/v2/orders/{}"); none of it may
// appear in the result, which is why the comment is here and not in a test.
var B="/api/v1/users",A="/static/app.css";
function list(){return fetch("/api/v1/users")}
function one(id){return fetch(`/api/v2/orders/${id}`)}
function q(id){return fetch("/api/v2/items/"+id)}
function save(b){return axios.post("/api/v3/things",b)}
function legacy(){return $.ajax({url:"/api/legacy/ping",method:"GET"})}
// not a route: /api/never-appears
export{B,list,one,q,save,legacy};
